select 'backup' k, count(*) n from bak_20261116_hold_restore
union all select 'held_manual', count(*) from yt_channel_videos y join bak_20261116_hold_restore b using(id) where y.content_flag='보류' and y.flag_source='manual' and b.content_flag is null
union all select 'group_changed', count(*) from yt_channel_videos y join bak_20261116_hold_restore b using(id) where y.group_ko<>b.group_ko
union all select 'members_trimmed', count(*) from yt_channel_videos y join bak_20261116_hold_restore b using(id) where y.group_ko=b.group_ko and y.content_flag is null and y.members<>b.members
union all select 'untouched', count(*) from yt_channel_videos y join bak_20261116_hold_restore b using(id) where y.group_ko=b.group_ko and y.members=b.members and y.content_flag is not distinct from b.content_flag;
